<?php declare(strict_types=1); require_once __DIR__.'/../includes/bootstrap.php'; header('Content-Type: application/json; charset=utf-8'); $rows=[]; try{$rows=$db->query("SELECT c.id,c.title,c.slug,c.description,c.level,c.featured,lc.name category_name,lc.icon category_icon,(SELECT COUNT(*) FROM learning_lessons l WHERE l.course_id=c.id AND l.enabled=1) lesson_count FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.enabled=1 ORDER BY c.featured DESC,c.id DESC")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'error'=>'Unable to load courses']);exit;} echo json_encode(['ok'=>true,'courses'=>$rows],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);